21	/**
22	 * The data type representing {@code java.math.BigDecimal} values. A Decimal that must have fixed
23	 * precision (the maximum number of digits) and scale (the number of digits on right side of dot).
24	 *
25	 * <p>The precision can be up to 38, scale can also be up to 38 (less or equal to precision).
26	 *
27	 * <p>The default precision and scale is (10, 0).
28	 *
29	 * @since 3.0.0
30	 */
31	@Evolving
32	public final class DecimalType extends DataType {
33	  public static final DecimalType USER_DEFAULT = new DecimalType(10, 0);
34	
35	  private final int precision;
36	  private final int scale;
37	
38	  public DecimalType(int precision, int scale) {
39	    if (precision < 0 || precision > 38 || scale < 0 || scale > 38 || scale > precision) {
40	      throw new IllegalArgumentException(
41	          String.format(
42	              "Invalid precision and scale combo (%d, %d). They should be in the range [0, 38] "
43	                  + "and scale can not be more than the precision.",
44	              precision, scale));
45	    }
46	    this.precision = precision;
47	    this.scale = scale;
48	  }
49	
50	  /** @return the maximum number of digits of the decimal */
51	  public int getPrecision() {
52	    return precision;
53	  }
54	
55	  /** @return the number of digits on the right side of the decimal point (dot) */
56	  public int getScale() {
57	    return scale;
58	  }
59	
60	  @Override
61	  public boolean isNested() {
62	    return false;
63	  }
64	
65	  @Override
